python3 - <<'PY'
import workcell
# search lattice pitch 0.025, radial shell 0.05-0.11 mm
pts=[]
for iy in range(-5,6):
 for ix in range(-5,6):
  x=397.04+ix*.025;y=284.31+iy*.025
  rad=max(abs(ix),abs(iy))
  if rad in (2,3,4,5) and not (abs(ix)<=2 and abs(iy)<=2):pts.append((rad,x,y))
pts.sort(key=lambda t:t[0]);
for rad,x,y in pts:
 r=workcell.call('robot','insert',f'{x:.3f}',f'{y:.3f}')
 print(f'{x:.3f} {y:.3f} {r.ok} {r.text}',flush=True)
 if r.ok:break
